    # Build full 4x5x6 decomposition with rank 112
    n, m, p = 4, 5, 6
    rank = 112
    U = [[0]*rank for _ in range(n*m)]  # (20, 112)
    V = [[0]*rank for _ in range(m*p)]  # (30, 112)
    W = [[0]*rank for _ in range(p*n)]  # (24, 112)

    col = 0

    # Block 1: 3x3x3 for A[0:3,0:3] @ B[0:3,0:3] -> C[0:3,0:3]
    # Uses columns col..col+22
    for c in range(23):
        for i in range(3):
            for j in range(3):
                U[i*m+j][col+c] = U333[i*3+j][c]
                V[j*p+k][col+c] = V333[j*3+k][c]  # Wait, need k
    # Let me redo this properly

    # Reset and do it correctly
    U = [[0]*rank for _ in range(n*m)]
    V = [[0]*rank for _ in range(m*p)]
    W = [[0]*rank for _ in range(p*n)]

    col = 0

    def add_333(U, V, W, col, i0, j0, k0):
        """Add a 3x3x3 Landsberg decomposition at offset (i0,j0,k0) in the full problem."""
        global col
        for c in range(23):
            for i in range(3):
                for j in range(3):
                    if U333[i*3+j][c] != 0:
                        U[(i0+i)*m + (j0+j)][col+c] += U333[i*3+j][c]
                for k in range(3):
                    if V333[j*3+k][c] != 0:
                        V[(j0+j)*p + (k0+k)][col+c] += V333[j*3+k][c]
                    if W333[k*3+i][c] != 0:
                        W[(k0+k)*n + (i0+i)][col+c] += W333[k*3+i][c]
        col += 23

    # Decomposition plan:
    # C[0:3,0:3] gets contribution from A[0:3,0:3]@B[0:3,0:3]  -> 3x3x3 (23 terms)
    # C[0:3,3:6] gets contribution from A[0:3,0:3]@B[0:3,3:6]  -> 3x3x3 (23 terms)  
    # C[0:3,3:6] also from A[0:3,3:5]@B[3:5,3:6] -> 3x2x3
    # C[0:3,3:6] also from A[0:3,0:2]@B[2:5,3:6] -> 3x3x3 (23 terms)
    # ... this is getting complicated. Let me use a cleaner recursive structure.

    # Cleaner approach:
    # Step 1: Split n=4 into 3+1
    #   C[0:3,:] = A[0:3,:] @ B  (3x5x6)
    #   C[3:4,:] = A[3:4,:] @ B  (1x5x6) = 30 terms
    # Step 2: For 3x5x6, split m=5 into 3+2
    #   A[0:3,0:3] @ B[0:3,:]  (3x3x6)
    #   A[0:3,3:5] @ B[3:5,:]  (3x2x6)
    # Step 3: For 3x3x6, split p=6 into 3+3
    #   A[0:3,0:3] @ B[0:3,0:3]  (3x3x3) = 23
    #   A[0:3,0:3] @ B[0:3,3:6]  (3x3x3) = 23
    # Step 4: For 3x2x6, split p=6 into 2+4... or just schoolbook = 3*2*6=36
    #   Actually 3x2x6 schoolbook = 36, but we can do better
    #   Split m=2 into 1+1: 2*(3x1x6) = 2*18 = 36. Same.
    #   So total: 23+23+36+30 = 112. 

    # Let me redo with this structure:
    U = [[0]*rank for _ in range(n*m)]
    V = [[0]*rank for _ in range(m*p)]
    W = [[0]*rank for _ in range(p*n)]
    col = 0

    # Part 1: 3x3x3 for A[0:3,0:3] @ B[0:3,0:3] -> C[0:3,0:3]
    add_333(U, V, W, col, 0, 0, 0)  # col 0-22

    # Part 2: 3x3x3 for A[0:3,0:3] @ B[0:3,3:6] -> C[0:3,3:6]
    add_333(U, V, W, col, 0, 0, 3)  # col 23-45

    # Part 3: 3x2x6 schoolbook for A[0:3,3:5] @ B[3:5,:] -> C[0:3,:]
    # 3*2*6 = 36 terms
    for i in range(3):
        for j in range(2):
            for k in range(6):
                U[(0+i)*m + (3+j)][col] = 1
                V[(3+j)*p + k][col] = 1
                W[k*n + (0+i)][col] = 1
                col += 1
    # col now at 46+36=82

    # Part 4: 1x5x6 schoolbook for A[3:4,:] @ B -> C[3:4,:]
    # 1*5*6 = 30 terms
    for j in range(5):
        for k in range(6):
            U[3*m + j][col] = 1
            V[j*p + k][col] = 1
            W[k*n + 3][col] = 1
            col += 1
    # col now at 82+30=112

    return {"U": U, "V": V, "W": W}
